const input = $input.first().json;
const body = input.body ?? input;

const sourceText = String(body.sourceText ?? "").trim();

const allowedPlatforms = [
  "linkedin",
  "instagram",
  "x",
  "blog",
  "newsletter"
];

const platforms = Array.isArray(body.platforms)
  ? [...new Set(body.platforms)]
  : [];

const allowedTones = [
  "professional",
  "casual",
  "educational",
  "persuasive",
  "friendly"
];

const errors = [];

if (sourceText.length < 50) {
  errors.push("Source text must contain at least 50 characters.");
}

if (sourceText.length > 20000) {
  errors.push("Source text must not exceed 20000 characters.");
}

if (platforms.length === 0) {
  errors.push("Select at least one platform.");
}

if (platforms.some(p => !allowedPlatforms.includes(p))) {
  errors.push("An unsupported platform was selected.");
}

const tone = String(body.tone ?? "professional")
  .trim()
  .toLowerCase();

if (!allowedTones.includes(tone)) {
  errors.push("Unsupported tone.");
}

const targetAudience = String(
  body.targetAudience ?? "general audience"
).trim();

const language = String(body.language ?? "English").trim();

if (targetAudience.length > 200) {
  errors.push("Target audience is too long.");
}

if (language.length > 50 || !language) {
  errors.push("Provide a valid language.");
}

if (errors.length > 0) {
  throw new Error(errors.join(" "));
}

return [{
  json: {
    sourceText,
    platforms,
    tone,
    targetAudience,
    language
  }
}];

